def short_hook(title, lesson_id=''):
    t=title.lower()
    if lesson_id in scene_hooks: return scene_hooks[lesson_id]
    if t in {'куда едем','цена до поездки','прямо и налево','останови здесь','чуть подожди'}:
        return {'куда едем':'В такси без паники: называем, куда везти.','цена до поездки':'Доехали ещё не все — сначала разберёмся с ценой и счётчиком.','прямо и налево':'Показываем дорогу словами: прямо, налево и вот тот поворот.','останови здесь':'Увидели свой сои — спокойно просим остановиться у входа.','чуть подожди':'Водитель ждёт, вы на минутку: просим подождать по-тайски.'}[t]
    if 'привет' in t: return 'С этого начинается почти любой разговор: поздоровались — и уже не чужие.'
    if 'знаком' in t or t in {'я и ты','он, она, они','семья','друзья и гости','мой, твой, его'}: return 'Кун Кру знакомит вас с людьми и словами, которыми здесь называют своих.'
    if 'как дела' in t or 'эмоци' in t: return 'Спросим, как человек, и ответим по-человечески — не одним сухим «нормально».'
    if any(x in t for x in ['тон','интонац','падение','подъём','быстрая речь','хвостики','каа','кхрап']): return 'Слушаем мелодию фразы и ловим маленькую деталь, из-за которой тайский звучит по-тайски.'
    if any(x in t for x in ['числа','время','дни недели','который час','раз']): return 'Цифры, часы и дни — чтобы договориться, купить и не прийти завтра вместо сегодня.'
    if any(x in t for x in ['цена','сколько','деньги','счёт','сумма','пиво']): return 'Спросим цену или счёт спокойно — без долгого объяснения на пальцах.'
    if any(x in t for x in ['просьб','сделай','уберите','почините','можно пораньше','подожди','жду']): return 'Просьба короткая, тон мягкий — и человек понимает, что от него нужно.'
    if any(x in t for x in ['где тут','прямо','налево','направо','метров','ориентир','адрес']): return 'Показываем, где это находится, чтобы вас поняли с первого раза.'
    if any(x in t for x in ['вкусно','остро','красиво','горячо','холодно','большой','маленький','хороший','плохой','новый','старый','быстрый']): return 'Описываем еду и вещи так, как это делают в обычной тайской жизни.'
    if any(x in t for x in ['такси','таксист','аэропорт','grab']): return 'Одна полезная остановка в тайской поездке — от адреса до оплаты.'
    if any(x in t for x in ['рынок','магазин','7-eleven','кафе','еда','заказ']): return 'Идём за покупкой или едой и берём с собой правильные фразы.'
    if any(x in t for x in ['полици','пост','паспорт','виза','иммиграц','документ']): return 'Кун Кру рядом на официальном разговоре: документы, вопросы и спокойный ответ.'
    if any(x in t for x in ['доктор','медицин','врач','страхов','помощь','срочн']): return 'Когда важно объяснить точно: где болит, что случилось и какая помощь нужна.'
    if any(x in t for x in ['кондо','дом','хозяин','сосед','правила','кондиционер','сервис']): return 'Разговор для дома в Таиланде: сообщаем, уточняем и договариваемся с хозяином или сервисом.'
    if any(x in t for x in ['достав','курьер']): return 'Курьер уже рядом — называем адрес, ориентир и место встречи.'
    if any(x in t for x in ['работ','коллег','статус','small talk','комплимент']): return 'Рабочий тайский без канцелярита: коротко спросить, уточнить и ответить.'
    if any(x in t for x in ['конфликт','резк','мягк','понятн','без давления','скрытые смыслы']): return 'Кун Кру покажет, как сказать прямо, но не обидно.'
    if any(x in t for x in ['блог','хобби','движ','ретрит','романтик','дет','мем','юмор','сонгкран','пляж','вечер','музык','танц']): return 'Живой тайский для ситуации, которая случается не в уроке, а после него.'
    if 'спасибо' in t or 'извини' in t or 'свидания' in t: return 'Красиво закончить разговор — тоже важная часть тайского.'
    if 'сценк' in t or 'диалог' in t or 'сборный' in t: return f'Кун Кру собирает тему «{title.lower()}» в одну короткую сценку из жизни.'
    return f'Кун Кру разберёт «{title.lower()}» коротко и по жизни.'

