lines += ['', '## Lesson-level tables','', 'Каждый hook рассчитан на одну короткую строку. Он не описывает механику тренировки и не заменяет карточки; он объясняет пользователю, о чём этот урок в его реальной тайской жизни.', '']
for cid,(block,ctitle,old_goal) in old_course_goals.items():
    lines += [f'### `{cid}` — {ctitle}', '', '| Lesson | Как сейчас | Cards | Как предлагаем: короткий hook |', '|---|---|---:|---|']
    for r in by.get(cid,[]):
        lines.append(f"| `{r['lesson_id']}` | {r['lesson_title']} | {r['record_count'] or '—'} | {short_hook(r['lesson_title'], r['lesson_id'])} |")
    lines.append('')
lines += ['## Правило для утверждения', '', 'Сначала согласовываем voice и формулировки. Только после этого решаем, какие существующие карточки оставить, переместить, объединить или дополнить. До отдельного OK пользователя исходные данные и main branch не меняются.']
Path('curriculum_goals_table_kun_kru_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('courses',len(old_course_goals),'lessons',len(rows))
